window.docContents[228].resolve({"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Quantum-enveloping-algebra-U_q_LPAR_sl_LPAR_2_RPAR__RPAR_-and-its-irreducible-representations/#Chapter2___Problem2___16___5":{"contents":"Problem 2.16.5. Let k be an algebraically closed field of characteristic zero, and let q \\in k^\\times, q \\neq \\pm 1. The quantum enveloping algebra \\mathcal{U}_q(\\mathfrak{sl}(2)) is the algebra generated by e, f, K, K^{-1} with relations\n\nKeK^{-1} = q^2 e, \\quad KfK^{-1} = q^{-2} f, \\quad [e, f] = \\frac{K - K^{-1}}{q - q^{-1}}\n\n(if you formally set K = q^h, you'll see that this algebra, in an appropriate sense, \"degenerates\" to \\mathcal{U}(\\mathfrak{sl}(2)) as q \\to 1). Classify irreducible\nrepresentations of \\mathcal{U}_q(\\mathfrak{sl}(2)). Consider separately the cases of q being a root of unity and q not being a root of unity.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.16. Problems on Lie algebras\tQuantum enveloping algebra U_q(sl(2)) and its irreducible representations","header":"Quantum enveloping algebra U_q(sl(2)) and its irreducible representations","id":"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Quantum-enveloping-algebra-U_q_LPAR_sl_LPAR_2_RPAR__RPAR_-and-its-irreducible-representations/#Chapter2___Problem2___16___5"},"/6___-Quiver-representations/Quiver-representations-_LPAR_chapter-heading_RPAR_/Quiver-representations/#Chapter6___Introduction___heading-1":{"contents":"","context":"Introduction to Representation Theory\t6. Quiver representations\tQuiver representations (chapter heading)","header":"Quiver representations","id":"/6___-Quiver-representations/Quiver-representations-_LPAR_chapter-heading_RPAR_/Quiver-representations/#Chapter6___Introduction___heading-1"}});
